const input = $input.first().json;

const originalJobs = $('Webhook').first().json.body.jobs || [];
const datePostedByJobId = {};
for (const j of originalJobs) { datePostedByJobId[j.job_id] = j.date_posted || ""; }

let text = "";

// Gemini output is usually here in your workflow
if (input.content && input.content.parts && input.content.parts[0] && input.content.parts[0].text) {
  text = input.content.parts[0].text;
} else if (input.text) {
  text = input.text;
} else if (input.output) {
  text = input.output;
} else if (input.response) {
  text = input.response;
} else if (input.message) {
  text = input.message;
} else {
  throw new Error("Could not find Gemini text output. Full input: " + JSON.stringify(input));
}

// Clean Gemini formatting if it ever adds markdown
text = text
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let jobs;

try {
  jobs = JSON.parse(text);
} catch (error) {
  throw new Error("Could not parse Gemini response as JSON. Raw Gemini response: " + text);
}

if (!Array.isArray(jobs)) {
  if (jobs && typeof jobs === "object") {
    jobs = [jobs];
  } else {
    throw new Error("Gemini response was not an array or object. Raw Gemini response: " + text);
  }
}

return jobs.map(job => {
  return {
    json: {
      job_id: job.job_id || "",
      date_posted: datePostedByJobId[job.job_id] || "",
      title: job.title || "",
      company: job.company || "",
      location: job.location || "",
      url: job.url || "",
      match_score: job.match_score || 0,
      tech_stack: Array.isArray(job.tech_stack)
        ? job.tech_stack.join(", ")
        : job.tech_stack || "",
      missing_skills: Array.isArray(job.missing_skills)
        ? job.missing_skills.join(", ")
        : job.missing_skills || "",
      pitch: job.pitch || "",
      tailored_resume_bullets: JSON.stringify(job.tailored_resume_bullets || []),
      tailored_summary: job.tailored_summary || "",
      tailored_skills: JSON.stringify(job.tailored_skills || [])
    }
  };
});

const original = $('Drop below 40').item.json;
const input = $input.first().json;

let text = "";
if (input.content && input.content.parts && input.content.parts[0] && input.content.parts[0].text) {
  text = input.content.parts[0].text;
} else if (input.text) {
  text = input.text;
} else if (input.output) {
  text = input.output;
} else if (input.response) {
  text = input.response;
} else {
  text = JSON.stringify(input);
}

text = text.replace(/```/g, "").trim();

return [{ json: { ...original, cover_letter: text } }];
